window.addEventListener('DOMContentLoaded',()=>{'use strict';
const $=id=>document.getElementById(id),P=GlyphPresets,D=GlyphDesign,auth=window.GLYPH_BRIDGE,stage=$('preset-preview');let state=null,revision=-1,working=false;
const report=t=>$('preset-status').textContent=t.message||String(t);
async function api(route,body){if(!auth)throw Error('Open the local dev server to create and save presets.');const r=await fetch('/api/'+route,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+auth.token,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})}),d=await r.json();if(!r.ok)throw Error(d.error?.message||'Preset operation failed.');return d;}
function lock(value){working=value;for(const id of ['preset-save-button','preset-reset','preset-current'])$(id).disabled=value||!auth;}
function preview(scene){stage.scene=scene;$('preset-json').textContent=JSON.stringify(scene,null,2);$('preset-api').textContent='// Exported presets are data, never executable code.\nconst next = GlyphPresets.append(currentScene, preset);\n// Motion-only preset, preserving geometry and content:\nconst moving = GlyphPresets.animate(currentScene, motionPreset);';}
function download(p){const url=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)+'\n'],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=p.id+'.preset.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function seed(scene){if(working)return;lock(true);try{const result=await api('presets/draft',{scene,expected_revision:revision});revision=result.draft.revision;state.draft=result.draft;preview(result.draft.scene);report('Draft updated. Prompt the designer to refine it.');}catch(e){report(e);}finally{lock(false);}}
function cards(){const list=state.presets;$('saved-presets').replaceChildren();if(!list.length){$('saved-presets').textContent='No custom presets yet. Your first variation starts above.';return;}for(const p of list){const card=document.createElement('article');card.className='saved-card';const tag=document.createElement('span'),h=document.createElement('h3'),desc=document.createElement('p'),actions=document.createElement('div');tag.className='tag';tag.textContent=p.kind.toUpperCase()+' / CUSTOM';h.textContent=p.name;desc.textContent=p.description||'Reusable seeded recipe';actions.className='saved-actions';function button(label,fn){const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=async()=>{if(working)return;try{await fn();}catch(e){report(e);}};actions.append(b);}button('Edit a copy',async()=>{await seed(p.scene);$('preset-kind').value=p.kind;$('preset-name').value=p.name+' / variation';$('preset-description').value=p.description;});if(p.kind==='motion')button('Try on draft',async()=>seed(P.animate(state.draft.scene,p)));button(p.kind==='motion'?'Apply to scene ↗':'Add to scene ↗',async()=>{lock(true);try{const current=await api('state'),scene=P.append(current.scene,p);await api('tool',{name:'glyph_studio_apply',arguments:{scene,expected_revision:current.revision}});report(p.name+' '+(p.kind==='motion'?'applied':'added')+' to the current scene.');}finally{lock(false);}});button('Export ↓',()=>download(p));card.append(tag,h,desc,actions);$('saved-presets').append(card);}}
async function refresh(){if(!auth||working)return;try{const next=await api('presets'+(state?'?revision='+state.revision+'&draft_revision='+revision:''));if(next.unchanged)return;const libraryChanged=!state||state.revision!==next.revision;state=next;if(revision!==next.draft.revision){revision=next.draft.revision;preview(next.draft.scene);}if(libraryChanged)cards();}catch(e){report(e);}}
$('preset-save').onsubmit=async e=>{e.preventDefault();if(working||!state)return;lock(true);try{const name=$('preset-name').value.trim(),slug=name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,40)||'preset',id='custom-'+slug+'-'+crypto.randomUUID().slice(0,8),preset=P.create(state.draft.scene,{kind:$('preset-kind').value,id,name,description:$('preset-description').value.trim()});state=await api('presets/save',{preset,expected_revision:state.revision,expected_draft_revision:revision});cards();report('Saved '+name+' to the design system. Reuse it below, or export its portable JSON.');}catch(e){report(e);}finally{lock(false);}};
$('preset-base').replaceChildren(...D.catalog().objects.map(o=>new Option(o.name,o.id)));$('preset-base').value='ribbon';$('preset-reset').onclick=()=>seed(D.scene({object:$('preset-base').value}));$('preset-current').onclick=async()=>{try{await seed((await api('state')).scene);}catch(e){report(e);}};$('preset-refresh').onclick=refresh;$('preset-pause').onclick=()=>{$('preset-pause').textContent=stage.toggleAttribute('paused')?'Play':'Pause';};stage.addEventListener('glyph-ready',e=>$('preset-stats').textContent=e.detail.instances+' GLYPHS / '+e.detail.renderer.toUpperCase()+' / DETERMINISTIC LOOP');stage.addEventListener('glyph-error',e=>report(e.detail));
if(auth){refresh();setInterval(()=>{if(!document.hidden)refresh();},1000);}else{preview(D.scene({object:'ribbon'}));lock(false);report('Run npm run dev and open /presets to connect the designer and your library.');}
});
